<?php declare(strict_types=1); namespace Silao\Tests\Unit\Infrastructure\Mapper; use PHPUnit\Framework\TestCase; use Silao\Domain\Customer\Customer; use Silao\Domain\Customer\ValueObject\CustomerId; use Silao\Domain\Customer\ValueObject\Email; use Silao\Domain\Customer\ValueObject\PhoneNumber; use Silao\Infrastructure\Exception\PersistenceException; use Silao\Infrastructure\Mapper\CustomerMapper; final class CustomerMapperTest extends TestCase { public function testGuestCustomerRoundTrip(): void { $customer = new Customer(CustomerId::fromString("cust_1"), Email::fromString("guest@example.com"), "Jane", "Doe", PhoneNumber::fromString("+33 6 12 34 56 78")); $dbData = CustomerMapper::toDatabase($customer); $this->assertSame("cust_1", $dbData["customer_id"]); $this->assertNull($dbData["wp_user_id"]); $hydrated = CustomerMapper::toDomain($dbData); $this->assertSame("cust_1", $hydrated->id()->toString()); $this->assertSame("guest@example.com", $hydrated->email()->toString()); $this->assertTrue($hydrated->isGuest()); } public function testRegisteredCustomerRoundTrip(): void { $customer = new Customer(CustomerId::fromString("cust_2"), Email::fromString("user@example.com"), "Alice", "Smith", null, 42); $dbData = CustomerMapper::toDatabase($customer); $this->assertSame(42, $dbData["wp_user_id"]); $hydrated = CustomerMapper::toDomain($dbData); $this->assertTrue($hydrated->isRegistered()); $this->assertSame(42, $hydrated->wpUserId()); } public function testCorruptedCustomerRowThrowsPersistenceException(): void { $this->expectException(PersistenceException::class); CustomerMapper::toDomain(["customer_id" => "c1"]); } }